Looking at the code fragments and the Hexi library's patterns, I can see how to implement the deserialization functions. Based on the test examples, I can see that:

1. Hexi uses `binary_stream` for serialization/deserialization
2. It supports adaptors like `null_terminated()` and `prefixed()` for strings
3. Containers can be read with special handling
4. The library supports `span()` for zero-copy views and `skip()` for skipping data

Here's the complete implementation:

```cpp
#include <hexi/hexi.h>
#include <vector>
#include <string>
#include <cstdint>
#include <span>

struct NetworkPacket {
    uint32_t packet_id;
    std::string username;
    std::vector<uint32_t> scores;
    std::string metadata;
};

NetworkPacket deserialize_packet(const std::span<const uint8_t> buffer) {
    NetworkPacket packet;

    // Create a buffer adaptor and binary stream for reading
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    // Read the packet_id
    stream >> packet.packet_id;

    // Read the username using length prefix (default string behavior)
    stream >> packet.username;

    // Read the score count, then read the scores vector using read_container
    uint32_t score_count;
    stream >> score_count;
    packet.scores.resize(score_count);
    for (uint32_t i = 0; i < score_count; ++i) {
        stream >> packet.scores[i];
    }

    // Read the metadata string as null-terminated
    stream >> hexi::null_terminated(packet.metadata);

    return packet;
}

struct PacketInfo {
    uint32_t packet_id;
    std::string_view username;
};

PacketInfo extract_packet_info(const std::span<const uint8_t> buffer) {
    PacketInfo info;

    // Create a buffer adaptor and binary stream for reading
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    // Use span() to get a zero-copy view of the packet_id (first 4 bytes)
    auto packet_id_span = stream.span<4>();
    // Copy the packet_id from the span
    std::memcpy(&info.packet_id, packet_id_span.data(), sizeof(uint32_t));

    // Read username using prefixed adaptor to get a string_view
    // First read the length prefix
    uint32_t username_length;
    stream >> username_length;

    // Get a zero-copy view of the username string
    auto username_span = stream.span(username_length);
    info.username = std::string_view(reinterpret_cast<const char*>(username_span.data()), username_length);

    // Skip the scores vector without reading its elements
    // Read count
    uint32_t score_count;
    stream >> score_count;

    // Skip the data (each score is a uint32_t)
    stream.skip(score_count * sizeof(uint32_t));

    return info;
}
```

