    hexi::binary_stream stream(adaptor);

    // Read the item count (uint32_t)
    std::uint32_t item_count = 0;
    stream >> item_count;

    // Create a vector to hold the items
    std::vector<std::uint32_t> items(item_count);

    // Read all items from the stream
    for (std::uint32_t i = 0; i < item_count; ++i) {
        stream >> items[i];
    }

    return items;
}

