Looking at the code fragments, I can see how to use the Hexi library's `buffer_adaptor` and `binary_stream` classes. Based on the test examples, I need to:

1. Create a `buffer_adaptor` from the span
2. Use `read_ptr()` to preview data without advancing the pointer
3. Create a `binary_stream` to read typed data
4. Read the header and then the items based on the data type

Here's the complete implementation:

```cpp
#include <hexi/hexi.h>
#include <vector>
#include <cstdint>
#include <span>

struct DataResult {
    uint8_t data_type;
    std::vector<uint32_t> int_items;
    std::vector<float> float_items;
};

DataResult preview_and_read_data(const std::span<const uint8_t> buffer) {
    DataResult result{};

    // Create buffer adaptor from the span
    hexi::buffer_adaptor adaptor(buffer);

    // Preview the first byte (data_type) without advancing the read pointer
    if (adaptor.size() < 1) {
        return result; // Not enough data
    }

    const auto* preview_ptr = adaptor.read_ptr();
    result.data_type = *preview_ptr;

    // Check if we have enough data for the header (1 byte + 4 bytes for item_count)
    if (adaptor.size() < sizeof(uint8_t) + sizeof(uint32_t)) {
        return result; // Not enough data for header
    }

    // Create binary stream for typed reading
    hexi::binary_stream stream(adaptor);

    // Read data_type (this advances the pointer)
    uint8_t data_type;
    stream >> data_type;

    // Read item_count
    uint32_t item_count;
    stream >> item_count;

    // Calculate required size for items
    size_t item_size = (data_type == 0) ? sizeof(uint32_t) : sizeof(float);
    size_t required_size = sizeof(uint8_t) + sizeof(uint32_t) + (item_count * item_size);

    // Check if we have enough data
    if (buffer.size() < required_size) {
        return result; // Not enough data for all items
    }

