This implementation:
1. Creates a `buffer_adaptor` from the input span
2. Uses `read_ptr()` to preview the first byte (data_type) without consuming it
3. Validates that sufficient data is available for the header
4. Creates a `binary_stream` for convenient typed reading
5. Reads the data_type and item_count from the header
6. Validates that sufficient data exists for all items
7. Reads the items based on the data_type (integers or floats) using the stream's `>>` operator

output.result:
#include <hexi/hexi.h>
#include <vector>
#include <cstdint>
#include <span>

struct DataResult {
    uint8_t data_type;
    std::vector<uint32_t> int_items;
    std::vector<float> float_items;
};

DataResult preview_and_read_data(const std::span<const uint8_t> buffer) {
    DataResult result{};

    // Create buffer adaptor from the span
    hexi::buffer_adaptor adaptor(buffer);

    // Preview the first byte (data_type) without advancing the read pointer
    if (adaptor.size() < 1) {
        return result; // Not enough data
    }

    const auto* preview_ptr = adaptor.read_ptr();
    result.data_type = *preview_ptr;

    // Check if we have enough data for the header (1 byte + 4 bytes for item_count)
    if (adaptor.size() < sizeof(uint8_t) + sizeof(uint32_t)) {
        return result; // Not enough data for header
    }

    // Create binary stream for typed reading
    hexi::binary_stream stream(adaptor);

    // Read data_type (this advances the pointer)
    uint8_t data_type;
    stream >> data_type;

    // Read item_count
    uint32_t item_count;
    stream >> item_count;

    // Calculate required size for items
    size_t item_size = (data_type == 0) ? sizeof(uint32_t) : sizeof(float);
    size_t required_size = sizeof(uint8_t) + sizeof(uint32_t) + (item_count * item_size);

    // Check if we have enough data
    if (buffer.size() < required_size) {
        return result; // Not enough data for all items
    }

    // Read items based on data_type
    if (data_type == 0) {
        // Read integers
        result.int_items.reserve(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            uint32_t value;
            stream >> value;
            result.int_items.push_back(value);
        }
    } else if (data_type == 1) {
        // Read floats
        result.float_items.reserve(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            float value;
            stream >> value;
            result.float_items.push_back(value);
        }
    }

    return result;
}

