#include <hexi/dynamic_tls_buffer.h>
#include <cstdint>

template<size_t block_size = 1024, size_t allocator_count = 100>
hexi::dynamic_tls_buffer<block_size, allocator_count> create_tls_buffer() {
    return hexi::dynamic_tls_buffer<block_size, allocator_count>{};
}

test cases:
#include <gtest/gtest.h>
#include <hexi/dynamic_tls_buffer.h>
#include <vector>
#include <cstdint>

// Include the implementation
#include "implementation.hpp"

TEST(TLSBuffer, CreateAndUse) {
    auto buffer = create_tls_buffer();

    std::vector<uint8_t> data = {1, 2, 3, 4, 5};
    buffer.write(data.data(), data.size());

    EXPECT_EQ(data.size(), buffer.size());
}

TEST(TLSBuffer, MultipleBuffersSharePool) {
    auto buffer1 = create_tls_buffer();
    auto buffer2 = create_tls_buffer();

    std::vector<uint8_t> data1 = {10, 20, 30};
    std::vector<uint8_t> data2 = {40, 50, 60};

    buffer1.write(data1.data(), data1.size());
    buffer2.write(data2.data(), data2.size());

    EXPECT_EQ(data1.size(), buffer1.size());
    EXPECT_EQ(data2.size(), buffer2.size());
}

TEST(TLSBuffer, WriteLargeData) {
    auto buffer = create_tls_buffer();
    std::vector<uint8_t> data(2000, 0xAA);

    buffer.write(data.data(), data.size());

    EXPECT_EQ(data.size(), buffer.size());
}

