```cpp
#include <hexi/file_buffer.h>
#include <vector>
#include <cstdint>
#include <filesystem>

std::vector<uint8_t> preview_file_header(const std::filesystem::path& file_path, size_t header_size) {
    // Create a file buffer from the given path
    hexi::file_buffer buffer(file_path);

    // Check if file was opened successfully
    if (!buffer) {
        return {};
    }

    // Ensure we don't try to read more than the file size
    size_t bytes_to_read = std::min(header_size, buffer.size());

    // Create destination vector with the appropriate size
    std::vector<uint8_t> header_data(bytes_to_read);

    // Read the header data into our vector
    buffer.read(header_data.data(), bytes_to_read);

    // The read pointer has advanced, but since we're done with this buffer
    // and return it, the original file is unaffected
    // If the caller needs the buffer with pointer at start, they would create a new file_buffer

    return header_data;
}
