```cpp
#include <hexi/static_buffer.h>

template<size_t buffer_size = 1024>
struct BufferInfo {
    size_t capacity;
    size_t current_size;
    size_t free_space;
};

BufferInfo<> get_buffer_info(const hexi::static_buffer<std::byte, 1024>& buffer) {
    BufferInfo<> info;

    // Get current readable data size
    info.current_size = buffer.size();

    // Get available free space
    info.free_space = buffer.free();

    // Calculate total capacity: current size + free space
    info.capacity = info.current_size + info.free_space;

    return info;
}

// Individual helper functions for specific queries

// Get the total capacity of a static_buffer
template<typename T, size_t N>
size_t get_buffer_capacity(const hexi::static_buffer<T, N>& buffer) {
    return buffer.size() + buffer.free();
}

// Get the current readable data size
template<typename T, size_t N>
size_t get_buffer_size(const hexi::static_buffer<T, N>& buffer) {
    return buffer.size();
}

// Get the available free space
template<typename T, size_t N>
size_t get_buffer_free_space(const hexi::static_buffer<T, N>& buffer) {
    return buffer.free();
}
```

