    hexi::pmc::binary_stream_reader reader(static_cast<hexi::pmc::buffer_read&>(buf_ref));
    std::uint32_t decoded = decode_varint<std::uint32_t>(reader);

    EXPECT_EQ(16384, decoded);
}

TEST(Varint, Roundtrip) {
    EXPECT_TRUE(encode_decode_roundtrip(std::uint8_t(0)));
    EXPECT_TRUE(encode_decode_roundtrip(std::uint8_t(127)));
    EXPECT_TRUE(encode_decode_roundtrip(std::uint16_t(128)));
    EXPECT_TRUE(encode_decode_roundtrip(std::uint32_t(16384)));
    EXPECT_TRUE(encode_decode_roundtrip(std::uint32_t(2097151)));
}

