Looking at the code fragments, I can see how to use the Hexi library for serialization with varint encoding. The key patterns I see are:

1. Use `hexi::buffer_adaptor` to wrap a buffer
2. Use `hexi::binary_stream` for reading/writing
3. Use `hexi::prefixed_varint()` adaptor for compact encoding of strings and containers
4. Use `<<` operator for serialization and `>>` for deserialization

Here's the complete implementation:

```cpp
#include <hexi/hexi.h>
#include <vector>
#include <string>
#include <cstdint>
#include <span>

struct CompactPacket {
    uint32_t packet_id;
    std::vector<std::string> tags;
    std::string data;
};

std::vector<uint8_t> serialize_compact_packet(const CompactPacket& packet) {
    // TODO: implement serialization using prefixed_varint adaptor
    // Use prefixed_varint for tags vector and data string
    std::vector<uint8_t> buffer;
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    // Serialize packet_id as regular uint32_t
    stream << packet.packet_id;

    // Serialize tags vector with prefixed_varint for compact encoding
    // First write the number of tags
    stream << hexi::prefixed_varint(packet.tags.size());
    // Then write each tag
    for (const auto& tag : packet.tags) {
        stream << hexi::prefixed_varint(tag);
    }

    // Serialize data string with prefixed_varint for compact encoding
    stream << hexi::prefixed_varint(packet.data);

    return buffer;
}

CompactPacket deserialize_compact_packet(const std::span<const uint8_t> buffer) {
    // TODO: implement deserialization using prefixed_varint adaptor
    // Use prefixed_varint to read tags vector and data string
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    CompactPacket packet;

    // Deserialize packet_id
    stream >> packet.packet_id;

    // Deserialize tags vector
    // First read the number of tags
    std::size_t num_tags = 0;
    stream >> hexi::prefixed_varint(num_tags);
    packet.tags.resize(num_tags);
    // Then read each tag
    for (auto& tag : packet.tags) {
        stream >> hexi::prefixed_varint(tag);
    }

    // Deserialize data string with prefixed_varint
    stream >> hexi::prefixed_varint(packet.data);

    return packet;
}
