std::vector<uint8_t> write_and_read_data(const std::vector<uint8_t>& input_data) {
    // TODO: create buffer, use buffer_write_adaptor to write data
    // Then use buffer_read_adaptor to read it back
    // Use write(), read(), free(), and size() methods

    // Create a buffer for writing
    std::vector<uint8_t> buffer;

    // Create write adaptor and write the input data
    hexi::pmc::buffer_write_adaptor write_adaptor(buffer);

    // Check available space before writing (should have enough space in a vector)
    auto free_space = write_adaptor.free();

    // Write the data to buffer
    write_adaptor.write(input_data.data(), input_data.size());

    // Create read adaptor to read the data back
    hexi::pmc::buffer_read_adaptor read_adaptor(buffer);

    // Check the readable size
    auto readable_size = read_adaptor.size();

    // Create output vector and read data back
    std::vector<uint8_t> output_data(readable_size);
    read_adaptor.read(output_data.data(), readable_size);

    return output_data;
}

std::vector<uint8_t> peek_data_without_advancing(const std::vector<uint8_t>& buffer_data, std::size_t peek_size) {
    // TODO: use buffer_read_adaptor with copy() to peek at data
    // Use read_ptr() to get pointer, copy() to peek, then read() to consume

    // Create a mutable copy of the buffer data (since we need non-const buffer)
    std::vector<uint8_t> buffer(buffer_data);

    // Create read adaptor
    hexi::pmc::buffer_read_adaptor read_adaptor(buffer);

    // Ensure we don't try to peek more than available
    std::size_t actual_peek_size = std::min(peek_size, read_adaptor.size());

    // Get pointer to current read position
    auto* read_ptr = read_adaptor.read_ptr();

    // Peek at data using copy() without advancing the read pointer
    std::vector<uint8_t> peeked_data(actual_peek_size);
    read_adaptor.copy(peeked_data.data(), actual_peek_size);

    // Now actually consume the data using read()
    std::vector<uint8_t> consumed_data(actual_peek_size);
    read_adaptor.read(consumed_data.data(), actual_peek_size);

    // Return the peeked data (both peeked_data and consumed_data should be the same)
    return peeked_data;
}
