#include <hexi/hexi.h>
#include <hexi/endian.h>
#include <vector>
#include <cstdint>
#include <span>

struct ProtocolPacket {
    uint32_t message_id;
    std::vector<uint16_t> data_values;
    uint32_t checksum;
};

std::vector<uint8_t> serialize_protocol_packet(const ProtocolPacket& packet) {
    // TODO: implement serialization with big-endian conversion
    // Use native_to_big for each field before writing
    // Use write() for scalars and write_container() for vectors

    std::vector<uint8_t> buffer;
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    // Convert and write message_id
    uint32_t message_id_be = hexi::endian::native_to_big(packet.message_id);
    stream.write(message_id_be);

    // Convert and write data_values
    std::vector<uint16_t> data_values_be;
    data_values_be.reserve(packet.data_values.size());
    for (const auto& value : packet.data_values) {
        data_values_be.push_back(hexi::endian::native_to_big(value));
    }
    stream.write_container(data_values_be);

    // Convert and write checksum
    uint32_t checksum_be = hexi::endian::native_to_big(packet.checksum);
    stream.write(checksum_be);

    return buffer;
}

ProtocolPacket deserialize_protocol_packet(const std::span<const uint8_t> buffer) {
    // TODO: implement deserialization with big-endian conversion
    // Read data, then use big_to_native to convert
    // Use read_container() for vectors

    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    ProtocolPacket packet;

    // Read and convert message_id
    uint32_t message_id_be;
    stream.read(message_id_be);
    packet.message_id = hexi::endian::big_to_native(message_id_be);

    // Read count of data_values
    uint32_t count_be;
    stream.read(count_be);
    uint32_t count = hexi::endian::big_to_native(count_be);

    // Read and convert data_values
    std::vector<uint16_t> data_values_be;
    stream.read_container(data_values_be, count);
    packet.data_values.reserve(count);
    for (const auto& value : data_values_be) {
        packet.data_values.push_back(hexi::endian::big_to_native(value));
    }

    // Read and convert checksum
    uint32_t checksum_be;
    stream.read(checksum_be);
    packet.checksum = hexi::endian::big_to_native(checksum_be);

    return packet;
}

struct ProtocolHeader {
    uint32_t message_id;
};

ProtocolHeader extract_protocol_header(const std::span<const uint8_t> buffer) {
    // TODO: implement header extraction using span() and big_to_native
    // Use span() to get message_id, convert with big_to_native, then skip

    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    ProtocolHeader header;

    // Get a zero-copy view of the first 4 bytes (message_id)
    auto message_id_span = stream.span<uint32_t>(1);

    // Convert from big-endian to native
    header.message_id = hexi::endian::big_to_native(message_id_span[0]);

    // Skip past the header (already consumed by span)
    // No need to skip since span already advanced the stream

    return header;
