Looking at the requirements and the code fragments provided, I need to implement functions for serializing and deserializing scientific measurement data with endianness conversion using the Hexi library.

Here's the complete implementation:

```cpp
#include <hexi/hexi.h>
#include <hexi/endian.h>
#include <vector>
#include <cstdint>
#include <string>

struct MeasurementData {
    uint32_t sensor_id;
    std::vector<float> temperatures;
    double pressure;

    void serialise(auto& adaptor) const {
        // Write sensor_id directly
        adaptor.write(&sensor_id, sizeof(sensor_id));

        // Write number of temperatures
        uint32_t temp_count = static_cast<uint32_t>(temperatures.size());
        adaptor.write(&temp_count, sizeof(temp_count));

        // Convert each temperature to little-endian and write
        for (const auto& temp : temperatures) {
            auto converted_temp = hexi::endian::conditional_reverse(temp, std::endian::native, std::endian::little);
            adaptor.write(&converted_temp, sizeof(converted_temp));
        }

        // Convert pressure to little-endian and write
        auto converted_pressure = hexi::endian::conditional_reverse(pressure, std::endian::native, std::endian::little);
        adaptor.write(&converted_pressure, sizeof(converted_pressure));
    }

    void serialise(auto& adaptor) {
        // Read sensor_id directly
        adaptor.read(&sensor_id, sizeof(sensor_id));

        // Read number of temperatures
        uint32_t temp_count = 0;
        adaptor.read(&temp_count, sizeof(temp_count));

        // Resize vector and read temperatures, then convert from little-endian to native
        temperatures.resize(temp_count);
        for (auto& temp : temperatures) {
            adaptor.read(&temp, sizeof(temp));
            hexi::endian::little_to_native_inplace(temp);
        }

        // Read pressure and convert from little-endian to native
        adaptor.read(&pressure, sizeof(pressure));
        hexi::endian::little_to_native_inplace(pressure);
    }
};

std::vector<uint8_t> serialize_measurement_data(const MeasurementData& data) {
    std::vector<uint8_t> buffer;
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    stream.serialise(data);

    return buffer;
}

MeasurementData deserialize_measurement_data(const std::span<const uint8_t> buffer) {
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    MeasurementData data;
    stream.deserialise(data);

    return data;
}

struct SensorInfo {
    uint32_t sensor_id;
    std::string_view sensor_name;
};

SensorInfo extract_sensor_info(const std::span<const uint8_t> buffer) {
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    SensorInfo info;

    // Extract null-terminated sensor name string
    info.sensor_name = stream.view();

    // Check if there's enough data to read sensor_id
    stream.enforce_read_bounds(sizeof(uint32_t));

    // Read sensor_id directly
    stream.read(&info.sensor_id, sizeof(info.sensor_id));

    // Skip the remaining data (temperatures count, temperatures, pressure)
    // Calculate remaining size: sizeof(uint32_t) for count + variable temps + sizeof(double) for pressure
    // Since we don't know the exact size, we skip all remaining data
    const auto remaining = stream.size();
    if (remaining > 0) {
        stream.skip(remaining);
    }

    return info;
}
```

This implementation:

1. **`serialize_measurement_data`**: Creates a buffer and binary stream, then uses `serialise` to write the structure. The const version of `serialise` writes sensor_id, converts temperatures and pressure from native to little-endian using `conditional_reverse` with runtime endianness parameters, then writes them.

2. **`deserialize_measurement_data`**: Creates a buffer adaptor from the input span and uses `deserialise` to read the structure. The non-const version of `serialise` reads sensor_id, reads temperatures and pressure, then converts them from little-endian to native using `little_to_native_inplace`.

3. **`extract_sensor_info`**: Uses `view()` to extract a null-terminated string, `enforce_read_bounds()` to verify sufficient data exists, reads the sensor_id, and uses `skip()` to skip remaining data.

